'use strict';
const Studio=(()=>{
 const esc=senEscape,stages=['Explore together','Practise with support','Try new examples','Use and revisit'];let token=0,timer=null;
 const old={title:skillTitle,art:skillArt,launch:skillLaunch,course:skillCourse,nav:skillNav,restore:skillRestoreRoute};
 const registry=()=>learningSkills.flatMap(s=>s.courses.map(c=>({...c,skillId:s.id,skillTitle:s.title})));
 for(const c of studioPilots){for(const a of c.activities){if(a.key==='build-word')a.key=readingGames.find(g=>g.mode==='spell').id;if(a.engine==='vocabulary')a.category=[...vocabularyCategories.keys()][0];}skillGet(c.skill).courses.push(c);}
 function go(hash){readingCancel();token++;clearTimeout(timer);if(location.hash!==hash)history.pushState(null,'',location.pathname+hash);route();}
 function nav(){old.nav();let n=document.getElementById('studioNav');if(!n){n=document.createElement('nav');n.id='studioNav';n.setAttribute('aria-label','Main navigation');document.querySelector('header').append(n);}n.innerHTML=[['support','Find support'],['courses','Courses'],['research','Research'],['practice','My practice']].map(([id,label])=>'<a href="#'+id+'">'+label+'</a>').join('');n.querySelectorAll('a').forEach(a=>a.onclick=e=>{if(e.ctrlKey||e.metaKey)return;e.preventDefault();go(a.hash);});document.body.classList.add('studio');document.querySelector('#brand').onclick=e=>{e.preventDefault();go('#support');};}
 function heading(label,title,copy){return '<section class="studio-hero"><span class="eyebrow">'+label+'</span><h1>'+esc(title)+'</h1><p>'+esc(copy)+'</p></section>';}
 function bind(){nav();app.querySelectorAll('[data-studio-course]').forEach(a=>a.onclick=e=>{e.preventDefault();skillCourse(a.dataset.studioCourse);});app.querySelectorAll('[data-studio-go]').forEach(a=>a.onclick=e=>{e.preventDefault();go(a.getAttribute('href'));});}
 function card(c){return '<article class="studio-card"><div class="studio-card-art" aria-hidden="true">'+skillArt(c.activities[0])+'</div><small>'+esc(c.skillTitle||skillGet(c.skill).title)+' · Adult joins in</small><h2><a href="#course/'+c.id+'" data-studio-course="'+c.id+'">'+esc(c.title)+'</a></h2><p>'+esc(c.goal)+'</p><span>'+c.activities.length+' activities'+(c.pilot?' · Four stages':'')+'</span><details><summary>Why this may help</summary><p>'+esc(c.need)+'</p></details></article>';}
 function courses(){skillContext=null;const p=new URLSearchParams(location.hash.split('?')[1]||''),query=p.get('q')||'',skill=p.get('skill')||'';app.innerHTML=heading('COURSES','Choose a useful learning goal','Short sessions, clear purposes and support you can adapt.')+'<form id="studioSearch"><label>Search courses<input value="'+esc(query)+'" placeholder="Words, attention or communication"></label><label>Skill<select><option value="">All skills</option>'+learningSkills.map(s=>'<option value="'+s.id+'" '+(skill===s.id?'selected':'')+'>'+esc(s.title)+'</option>').join('')+'</select></label><button class="primary">Find courses</button></form><p id="studioCount"></p><div class="studio-grid" id="studioResults"></div>';const found=registry().filter(c=>(!skill||c.skillId===skill)&&(!query||(c.title+' '+c.goal+' '+c.need).toLowerCase().includes(query.toLowerCase()))).sort((a,b)=>Number(!!b.pilot)-Number(!!a.pilot));app.querySelector('#studioCount').textContent=found.length+' courses';app.querySelector('#studioResults').innerHTML=found.map(card).join('')||'<p>No courses match. Try another word or all skills.</p>';app.querySelector('form').onsubmit=e=>{e.preventDefault();go('#courses?q='+encodeURIComponent(app.querySelector('input').value)+'&skill='+encodeURIComponent(app.querySelector('select').value));};bind();}
 function practice(){skillContext=null;let recent=null;try{recent=JSON.parse(localStorage.getItem('spotmatch-last-course-v1')||'null');}catch{}app.innerHTML=heading('MY PRACTICE','Return to a useful activity','Notes stay in this browser. Explored activities are not mastery scores.')+'<div class="studio-grid">'+(registry().filter(c=>skillNotes[c.id]||recent?.courseId===c.id).map(card).join('')||'<p>Start a course. Explored activities will appear here.</p>')+'</div><button id="studioExport" class="secondary">Export local practice</button><label>Import practice file<input id="studioImport" type="file" accept="application/json"></label><p id="studioImportStatus" role="status"></p>';app.querySelector('#studioExport').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({schemaVersion:1,notes:skillNotes})],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='spot-match-practice.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};app.querySelector('#studioImport').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>1000000)throw Error('Choose a practice file below 1 MB.');const data=JSON.parse(await file.text());if(data.schemaVersion!==1||!data.notes||typeof data.notes!=='object'||Array.isArray(data.notes))throw Error('Unsupported practice format.');const accepted={};for(const c of registry()){const value=data.notes[c.id];if(!value||typeof value!=='object')continue;const activities={};for(let i=0;i<c.activities.length;i++)if(value.activities?.[i]===true)activities[i]=true;accepted[c.id]={activities,offline:value.offline===true};}try{localStorage.setItem('spotmatch-practice-backup-v1',JSON.stringify(skillNotes));}catch{}Object.assign(skillNotes,accepted);skillSave();app.querySelector('#studioImportStatus').textContent='Imported; existing notes were backed up in this browser.';}catch(error){app.querySelector('#studioImportStatus').textContent=error.message;}};bind();}
 function research(){skillContext=null;const data=studioResearch,parts=location.hash.split('/'),type=parts[1],id=parts[2];if(type&&id){const item=(type==='journal'?data.journals:data.articles).find(x=>x.id===id);app.innerHTML=item?heading('RESEARCH',item.title||item.name,'Sources and review status')+'<article class="studio-reading"><p>'+esc(item.summary||item.scope||'')+'</p><dl>'+[['Review status',item.editorialStatus||item.credentialStatus],['Review depth',item.reviewLabel],['Year',item.year],['Journal',item.journalTitle],['Participants',item.population],['Design',item.studyDesign],['Limits',item.limitation],['Relationship to activities',item.relationship],['Corrections',item.correctionStatus],['Verification',item.verificationNote]].filter(x=>x[1]).map(([k,v])=>'<dt><b>'+esc(k)+'</b></dt><dd>'+esc(String(v))+'</dd>').join('')+'</dl><p><a href="'+esc(item.url||item.sourceUrl||'#research')+'" target="_blank" rel="noopener noreferrer">Open original source ↗</a></p><a href="#research" data-studio-go>Back to research</a></article>':'<h1>Research record not found</h1><a href="#research" data-studio-go>Back to research</a>';bind();return;}app.innerHTML=heading('RESEARCH','Understand the evidence','Original sources, plain-language notes and explicit review status.')+'<p class="studio-notice">Source notes are editorial drafts. Only records whose abstracts were read have abstract-based summaries. Independent review and some journal credentials remain pending.</p><label>Search research<input id="studioResearchSearch" type="search" placeholder="Reading, language or AAC"></label><label>Review depth<select id="studioReviewFilter"><option value="">All records</option><option value="abstract-only">Abstract read</option><option value="full-text">Full text reviewed</option></select></label><label>Study type<select id="studioDesignFilter"><option value="">All study types</option><option value="review">Reviews and meta-analyses</option><option value="trial">Trials</option></select></label><div id="studioArticles"></div><h2>Journal directory</h2><div class="studio-grid">'+data.journals.map(j=>'<article class="studio-card"><h3><a href="#research/journal/'+j.id+'" data-studio-go>'+esc(j.title||j.name)+'</a></h3><p>'+esc(j.scope||'Education and developmental research')+'</p><small>'+esc(j.editorialStatus||j.status||'Credentials pending verification')+'</small></article>').join('')+'</div><details><summary>Guidance and professional resources</summary>'+readingSources.map(s=>'<p><a href="'+s.url+'" target="_blank" rel="noopener noreferrer">'+esc(s.title)+'</a> — '+esc(s.note)+'</p>').join('')+'</details>';const render=()=>{const query=app.querySelector('#studioResearchSearch').value.toLowerCase();app.querySelector('#studioArticles').innerHTML=data.articles.filter(a=>JSON.stringify(a).toLowerCase().includes(query)&&(!app.querySelector('#studioReviewFilter').value||a.reviewScope===app.querySelector('#studioReviewFilter').value)&&(!app.querySelector('#studioDesignFilter').value||String(a.studyDesign||'').toLowerCase().includes(app.querySelector('#studioDesignFilter').value))).map(a=>'<article class="studio-research-card"><small>'+esc(a.reviewLabel||a.reviewScope||'Discovered reference; abstract not reviewed')+' · '+esc(a.editorialStatus||'Draft')+'</small><h2><a href="#research/article/'+a.id+'" data-studio-go>'+esc(a.title)+'</a></h2><p>'+esc(a.summary||'Open the original source for details.')+'</p></article>').join('')||'<p>No records match.</p>';bind();};app.querySelector('#studioResearchSearch').oninput=render;app.querySelector('#studioReviewFilter').onchange=render;app.querySelector('#studioDesignFilter').onchange=render;render();}
 function support(){skillHome();const intro=document.createElement('section');intro.className='studio-start';intro.innerHTML='<p>Find support for a difficulty you notice, or choose a learning goal.</p><a href="#courses" data-studio-go>Browse all courses →</a><div class="studio-pilots">'+studioPilots.map(c=>'<a href="#course/'+c.id+'" data-studio-course="'+c.id+'"><b>'+esc(c.title)+'</b><span>16 activities · Four stages</span></a>').join('')+'</div>';app.prepend(intro);bind();}
 skillTitle=a=>a.engine==='offline'?a.title:a.title||old.title(a);skillArt=a=>a.engine==='offline'?readingPicture('bag'):old.art(a);skillNav=nav;
 skillCourse=id=>{token++;clearTimeout(timer);old.course(id);const c=skillCourseGet(id).course;if(c.pilot){const section=app.querySelector('.skill-course-activities');section.innerHTML='<p class="studio-notice">Curriculum draft · Educator review pending. Adult support is needed. Try one to three activities for a short visit.</p><p><b>Start with:</b> '+esc(c.entry)+'</p>'+stages.map((stage,s)=>'<section class="studio-stage"><h2>'+(s+1)+'. '+stage+'</h2>'+c.activities.slice(s*4,s*4+4).map((a,j)=>'<button data-pilot-activity="'+(s*4+j)+'"><b>'+esc(a.title)+'</b><small>'+(a.engine==='offline'?'Together away from the screen':'Interactive game')+' · '+esc(a.purpose)+'</small></button>').join('')+'</section>').join('');section.querySelectorAll('button').forEach(b=>b.onclick=()=>skillLaunch(id,+b.dataset.pilotActivity));}nav();};
 function offline(id,index){const c=skillCourseGet(id).course,a=c.activities[index],instance=++token;let paused=false,completed=false,pending=null;skillContext={skillId:c.skill,courseId:id,index};skillWriteRoute('activity',id,index);const render=()=>{app.innerHTML='<section class="studio-offline"><button id="studioBack" class="back">← Back to course</button><span>'+(index+1)+' / 16 · Together away from the screen</span><h1>'+esc(a.title)+'</h1><div class="studio-offline-art">'+readingPicture('bag')+readingPicture('cup')+'</div><h2>'+esc(a.invitation)+'</h2><p><b>We are practising:</b> '+esc(a.purpose)+'</p><p><b>Try it together:</b> '+esc(a.adultModel)+'</p><details><summary>Adapt it for this child</summary>'+a.adaptations.map(x=>'<p>'+esc(x)+'</p>').join('')+'</details><p>'+esc(a.transfer)+'</p><button id="studioPause" class="secondary">'+(paused?'Resume':'Pause')+'</button><button id="studioTried" class="primary" '+(paused||completed?'disabled':'')+'>We tried this together</button><p role="status">'+(paused?'Paused. Take your time.':'Shared practice, not a correct-answer score.')+'</p></section>';app.querySelector('#studioBack').onclick=()=>skillCourse(id);app.querySelector('#studioPause').onclick=()=>{paused=!paused;clearTimeout(timer);if(!paused&&completed&&CourseFlow.enabled&&pending)timer=setTimeout(pending,1100);render();if(completed&&!CourseFlow.enabled&&pending){const b=document.createElement('button');b.id='studioOfflineContinue';b.className='primary';b.textContent='Continue';b.disabled=paused;b.onclick=pending;app.append(b);}};app.querySelector('#studioTried').onclick=()=>{if(paused||completed||instance!==token)return;completed=true;skillNotes[id]??={};skillNotes[id].activities??={};skillNotes[id].activities[index]=true;skillSave();app.querySelector('#studioTried').disabled=true;app.querySelector('[role=status]').textContent='Thanks for exploring together.';const next=()=>{if(instance!==token)return;if(index+1<16)skillLaunch(id,index+1);else skillCourse(id);};pending=next;if(CourseFlow.enabled)timer=setTimeout(next,1100);else{const b=document.createElement('button');b.textContent='Continue';b.id='studioOfflineContinue';b.className='primary';b.onclick=next;app.append(b);}};nav();};render();}
 skillLaunch=(id,index)=>{const c=skillCourseGet(id).course,a=c.activities[index];token++;clearTimeout(timer);try{localStorage.setItem('spotmatch-last-course-v1',JSON.stringify({courseId:id,index}));}catch{}if(a.engine==='offline'){offline(id,index);return;}old.launch(id,index);if(c.pilot){const note=document.createElement('section');note.className='wq-support';note.id='studioPurpose';note.innerHTML='<h2>Why this activity?</h2><p>We are practising: '+esc(a.purpose)+'</p><p>May be useful when: '+esc(c.need)+'</p><details><summary>Adult model and adaptations</summary><p>'+esc(a.adultModel)+'</p>'+a.adaptations.map(x=>'<p>'+esc(x)+'</p>').join('')+'<p>This sequence has not been evaluated as an intervention.</p></details>';app.append(note);}nav();};
 const decorate=skillDecorate;skillDecorate=()=>{decorate();if(!skillContext||skillContext.index===null||app.querySelector('#studioPurpose'))return;const c=skillCourseGet(skillContext.courseId).course;if(!c.pilot||!app.querySelector('.reading-play,.vocabulary-play'))return;const a=c.activities[skillContext.index],n=document.createElement('section');n.id='studioPurpose';n.className='wq-support';n.innerHTML='<h2>Why this activity?</h2><p>'+esc(a.purpose)+'</p><details><summary>Model and adapt</summary><p>'+esc(a.adultModel)+'</p>'+a.adaptations.map(x=>'<p>'+esc(x)+'</p>').join('')+'</details>';app.append(n);};
 function route(){const hash=location.hash;if(hash==='#support'||hash==='#skills'||!hash)support();else if(hash.startsWith('#courses'))courses();else if(hash.startsWith('#practice'))practice();else if(hash.startsWith('#research'))research();else{old.restore();nav();}}
 skillRestoreRoute=()=>{if(/^#(courses|research|practice)([/?]|$)/.test(location.hash)||location.hash==='#support'){route();return true;}return old.restore();};window.addEventListener('popstate',route);window.addEventListener('hashchange',route);nav();if(!location.hash||location.hash==='#skills'||location.hash==='#support')support();else route();return{registry,route,go};
})();
